                if (currentMode === 'emoji-stamp' && stampCursor) { stampCursor.style.left = (e.clientX - stampSize / 2) + 'px'; stampCursor.style.top = (e.clientY - stampSize / 2) + 'px'; }
                if (cursorDot && document.body.classList.contains('drawing-mode') && !document.body.classList.contains('laser-mode')) { cursorDot.style.left = e.clientX + 'px'; cursorDot.style.top = e.clientY + 'px'; }
