                    media: '<rect x="3" y="4.6" width="18" height="14.8" rx="2.6"/><circle cx="8.6" cy="10" r="1.7"/><path d="M4 17.2l4.6-4.2 3.6 3.2 3-2.6 5.8 5"/>',
                    ticker: '<rect x="3" y="5.6" width="18" height="5.4" rx="2.4"/><path d="M3 15h18"/>',
                    record: '<circle cx="12" cy="12" r="8.4"/><circle cx="12" cy="12" r="3.6" fill="currentColor" stroke="none"/>',
                    screen: '<rect x="2.6" y="4" width="18.8" height="12.4" rx="2"/><path d="M8.4 20.6h7.2"/><path d="M12 16.4v4.2"/>',
                    a11y: '<circle cx="12" cy="4.8" r="2"/><path d="M4.2 9.6l7.8 1.4 7.8-1.4"/><path d="M12 11v4"/><path d="M9 20.6l3-5.6 3 5.6"/>',
                    help: '<circle cx="12" cy="12" r="8.4"/><path d="M9.6 9.6a2.5 2.5 0 1 1 3.3 2.4c-.8.3-1.1 1-1.1 1.7v.4"/><path d="M12 17.4h.02"/>',
                    bookmark: '<path d="M7 3.6h10a1.5 1.5 0 0 1 1.5 1.5V21L12 17.6 5.5 21V5.1A1.5 1.5 0 0 1 7 3.6z"/>',
                    edit: '<path d="M4 20h4.2l10-10-4.2-4.2L4 15.8z"/><path d="M13.8 6l4.2 4.2"/>',
                    redo: '<path d="M20 9h-9.2a4.6 4.6 0 1 0 4.6 4.6"/><path d="M20 9l-3.6-3.6M20 9l-3.6 3.6"/>',
