                    painter: '<path d="M4.4 4.6h10.8v4.8H4.4z"/><path d="M9.8 9.4v3.2a1.8 1.8 0 0 0 1.8 1.8h1a1.8 1.8 0 0 1 1.8 1.8v3"/>',
                    font: '<path d="M5 19.4l5.4-13.4h1.2l5.4 13.4"/><path d="M7.6 14.6h8.8"/><path d="M4 21.6h16" stroke-width="2.6"/>',
                    paint: '<path d="M7 3.4l9.8 9.8-6 6a2 2 0 0 1-2.9 0l-3.3-3.3a2 2 0 0 1 0-2.9z"/><path d="M12.2 8.6l3-3"/><path d="M20 20.6c1.3-1.5 1.3-3.1 0-4.4"/>',
                    steps: '<path d="M9.4 6.6h11M9.4 12h11M9.4 17.4h11"/><path d="M4 4.6l1.6-1.2v5.2"/><path d="M3.6 12.2h2.3L3.6 14.6h2.4"/><path d="M3.6 17.2h2.4v1.4H4.3l1.7 1.6"/>',
                    snapshot: '<path d="M4 7.6h2.9l1.5-2.2h7.2l1.5 2.2H20a1.6 1.6 0 0 1 1.6 1.6v8.8A1.6 1.6 0 0 1 20 19.6H4A1.6 1.6 0 0 1 2.4 18V9.2A1.6 1.6 0 0 1 4 7.6z"/><circle cx="12" cy="13.2" r="3.7"/>',
                    wand: '<path d="M4 20.6l11-11"/><path d="M14.8 9.8l-3.2-3.2 1.7-1.7 3.2 3.2z"/><path d="M19 13.2l.8 1.9 1.9.8-1.9.8-.8 1.9-.8-1.9-1.9-.8 1.9-.8z"/>',
