            const customEmojiInput = document.getElementById('custom-emoji-input');
            const FA_ICONS = ['star','heart','fire','rocket','check','times','plus','smile','grin','laugh','crown','trophy','medal','gem','diamond','bolt','thumbs-up','thumbs-down','hand-peace','music','volume-up','microphone','video','camera','image','film','play','pause','stop','forward','backward','angle-right','angle-left','angle-up','angle-down','arrow-right','arrow-left','arrow-up','arrow-down','redo','undo','sync','refresh','spinner','eye','eye-slash','search','search-plus','filter','list','th','bars','plus-circle','minus-circle','times-circle','check-circle','info-circle','question-circle','exclamation-circle','warning','lightbulb','brain','graduation-cap','book','book-open','pen','pencil-alt','eraser','highlighter','paint-brush','palette','copy','clipboard','file','file-alt','folder','folder-open','save','download','upload','share','link','external-link-alt','print','envelope','phone','comment','comments','quote-left','quote-right','bell','alarm','clock','hourglass','calendar','calendar-alt','calendar-check','tasks','flag','flag-checkered','award','badge','shield-alt','lock','unlock','key','wrench','cog','tools','scissors','paperclip','pushpin','map-marker','globe','globe-americas','compass','location-arrow','car','bus','plane','paper-plane','ship','truck','bicycle','utensils','coffee','beer','birthday-cake','gift','balloon','party-horn','sun','moon','cloud','snowflake','umbrella','leaf','tree','seedling','paw','cat','dog','bug','bird','fish','frog','horse','ghost','skull','poo','robot','gamepad','dice','chess','chess-knight','chess-queen','chess-rook','baseball-ball','basketball-ball','football-ball','volleyball-ball','golf-ball','table-tennis','bowling-ball','stopwatch','running','walking','swimmer','dumbbell','heartbeat','heart-broken','kiss','grin-beam','grin-wink','surprise','sad-tear','angry','dizzy','flushed','frown','meh','tired','wink','wine-glass','cocktail','mug-hot','pizza','hamburger','ice-cream','apple-alt','lemon','pepper-hot','carrot','bread-slice','cheese','egg','drumstick-bite','shrimp','bone','tooth','smile-beam','spider','fire-extinguisher'];
            function renderFaSuggestions(query) {
                const dd = document.getElementById('fa-suggest-dropdown');
                if (!dd) return;
                const q = (query || '').toLowerCase().trim();
                if (!q) { dd.style.display = 'none'; return; }
                const matches = FA_ICONS.filter(n => n.indexOf(q) !== -1).slice(0, 60);
                if (matches.length === 0) {
                    dd.innerHTML = '<div style="padding:10px; text-align:center; color:#94a3b8; font-size:11px; font-style:italic;">No matching icons — try another keyword</div>';
                    dd.style.display = 'block';
                    return;
                }
                dd.innerHTML = '';
                matches.forEach(name => {
                    const row = document.createElement('div');
                    row.style.cssText = 'display:flex; align-items:center; gap:9px; padding:6px 8px; border-radius:8px; cursor:pointer; transition:background 0.12s;';
                    row.onmouseenter = () => { row.style.background = '#eef2ff'; };
                    row.onmouseleave = () => { row.style.background = 'transparent'; };
                    const icon = document.createElement('i');
                    icon.className = 'fas fa-' + name;
                    icon.style.cssText = 'width:20px; text-align:center; font-size:14px; color:#4f46e5; flex-shrink:0;';
                    const label = document.createElement('span');
                    label.textContent = 'fa-' + name;
                    label.style.cssText = 'font-size:11px; font-weight:600; color:#334155; font-family: monospace;';
                    row.appendChild(icon); row.appendChild(label);
                    row.onclick = (e) => {
                        e.stopPropagation();
                        const val = 'fa-' + name;
                        customEmojiInput.value = val;
                        dd.style.display = 'none';
                        selectEmoji(val, 'custom');
                    };
                    dd.appendChild(row);
                });
                dd.style.display = 'block';
            }
