        // Paste handler for detached window - show in preview, don't embed immediately
        const setupPasteHandler = () => {
            const pasteCatcher = document.getElementById('fc-paste-catcher');
            const emptyCanvas = document.getElementById('fc-empty-canvas');
            if (emptyCanvas) {
                emptyCanvas.onclick = () => {
                    if (pasteCatcher) { pasteCatcher.focus(); }
                };
            }
            if (pasteCatcher) {
                pasteCatcher.addEventListener('paste', (e) => {
                    e.preventDefault();
                    let file = null;
                    let fileType = '';
                    if (e.clipboardData.files && e.clipboardData.files.length > 0) {
                        file = e.clipboardData.files[0];
                        if (file.type.indexOf('image') === -1) file = null;
                        else fileType = file.type;
                    }
                    if (!file) {
                        const items = e.clipboardData.items;
                        for (let i = 0; i < items.length; i++) {
                            if (items[i].type.indexOf('image') !== -1) {
                                fileType = items[i].type;
                                file = items[i].getAsFile();
                                break;
                            }
                        }
                    }
                    if (!file) return;
                    const url = URL.createObjectURL(file);
                    const isGif = fileType === 'image/gif';
                    const label = '';
                    // Show in preview canvas
                    const view = document.getElementById('fc-media-view');
                    const wordView = document.getElementById('fc-word-view');
                    const attrib = document.getElementById('fc-pic-attrib-bubble');
                    const emptyEl = document.getElementById('fc-empty-canvas');
                    if (emptyEl) emptyEl.style.display = 'none';
                    if (view) {
                        if (isGif) {
                            view.innerHTML = '<video src="' + url + '" autoplay loop muted playsinline style="max-width:100%; max-height:100%; object-fit:contain;"></video>';
                        } else {
                            view.innerHTML = '<img src="' + url + '" style="max-width:100%; max-height:100%; object-fit:contain;" />';
                        }
                        const ta = document.createElement('textarea');
                        ta.id = 'fc-paste-catcher';
                        ta.style.cssText = 'position:absolute; width:0; height:0; opacity:0; pointer-events:none;';
                        ta.tabIndex = -1;
                        ta.setAttribute('aria-hidden', 'true');
                        view.appendChild(ta);
                        setTimeout(() => ta.focus(), 50);
                    }
                    if (wordView) {
                        wordView.textContent = '';
                        wordView.focus();
                    }
                    if (attrib) {
                        attrib.style.display = 'block';
                        attrib.textContent = isGif ? 'Animated GIF' : 'Pasted Image';
                    }
                    // Accumulate as album
                    if (fcSelectedMediaList.length > 0 && fcSelectedType === 'image') {
                        fcSelectedMediaList.push({ id: 'img_' + Date.now(), url: url, preview: url, title: '', caption: isGif ? 'Animated GIF' : 'Pasted image' });
                    } else {
                        fcSelectedType = 'image';
                        fcSelectedUrl = url;
                        fcSelectedWord = '';
                        fcSelectedCaption = isGif ? 'Animated GIF' : 'Pasted image';
                        fcSelectedMediaList = [];
                    }
                });
            }
        };
        setupPasteHandler();

